[metadata] {"type": "create", "filePath": "/workspace/repo/src/integrations/prefect-kubernetes/prefect_kubernetes/diagnostics.py", "content": """"Utilities for diagnosing Kubernetes pod failures.

This module inspects the ``status`` dictionary of a Kubernetes pod and turns
known failure conditions (image pull errors, out-of-memory kills, crash loops,
scheduling failures, evictions, ...) into structured, human-readable
diagnoses. The observer uses these diagnoses to surface actionable information
on a flow run's logs.
"""

from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
from typing import Any


class DiagnosisLevel(str, Enum):
    """Severity level for an infrastructure diagnosis."""

    ERROR = "error"
    WARNING = "warning"


@dataclass(frozen=True)
class InfrastructureDiagnosis:
    """A structured diagnosis of a Kubernetes pod failure.

    Instances are immutable (frozen) and compare by value.
    """

    level: DiagnosisLevel
    summary: str
    detail: str
    resolution: str


def _diagnose_container_waiting(
    name: str, waiting: dict[str, Any]
) -> InfrastructureDiagnosis | None:
    """Diagnose a container that is stuck in a ``waiting`` state."""
    reason = waiting.get("reason")
    message = waiting.get("message") or ""

    if reason in ("ImagePullBackOff", "ErrImagePull"):
        detail = f"{reason}: {message}" if message else reason
        return InfrastructureDiagnosis(
            level=DiagnosisLevel.ERROR,
            summary=f"Container '{name}' cannot pull its image ({reason})",
            detail=detail,
            resolution=(
                "Verify the image name and tag are correct and that the cluster "
                "has credentials to pull the image from its registry."
            ),
        )

    if reason == "CrashLoopBackOff":
        detail = f"{reason}: {message}" if message else reason
        return InfrastructureDiagnosis(
            level=DiagnosisLevel.ERROR,
            summary=f"Container '{name}' is crash-looping (CrashLoopBackOff)",
            detail=detail,
            resolution=(
                "Inspect the container logs to determine why the process keeps "
                "exiting and address the underlying error."
            ),
        )

    return None


def _diagnose_container_terminated(
    name: str, terminated: dict[str, Any]
) -> InfrastructureDiagnosis | None:
    """Diagnose a container that has ``terminated`` abnormally."""
    reason = terminated.get("reason")
    message = terminated.get("message") or ""

    if reason == "OOMKilled":
        detail = f"OOMKilled: {message}" if message else "OOMKilled"
        return InfrastructureDiagnosis(
            level=DiagnosisLevel.ERROR,
            summary=f"Container '{name}' was OOMKilled (ran out of memory)",
            detail=detail,
            resolution=(
                "Increase the memory request/limit for the container or reduce "
                "the memory the workload uses."
            ),
        )

    if reason == "Evicted":
        detail = f"Evicted: {message}" if message else "Evicted"
        return InfrastructureDiagnosis(
            level=DiagnosisLevel.WARNING,
            summary=f"Container '{name}' was evicted",
            detail=detail,
            resolution=(
                "Check node resource pressure and pod resource requests to avoid "
                "future evictions."
            ),
        )

    return None


def diagnose_k8s_pod(status: dict[str, Any]) -> InfrastructureDiagnosis | None:
    """Inspect a pod status dictionary for known failure conditions.

    Args:
        status: The ``status`` dictionary of a Kubernetes pod.

    Returns:
        An :class:`InfrastructureDiagnosis` describing a known failure
        condition, or ``None`` if the pod is healthy or in a state that does
        not require intervention.
    """
    if not status:
        return None

    # Scan both init containers and regular containers for failures. Init
    # container statuses are checked first so their names surface in the
    # diagnosis when they are the cause of the failure.
    container_statuses = list(status.get("initContainerStatuses", [])) + list(
        status.get("containerStatuses", [])
    )

    # Waiting-state failures (image pull errors, crash loops) take priority over
    # terminated-state failures (OOMKilled, evictions), so scan for them first.
    for container_status in container_statuses:
        name = container_status.get("name", "")
        state = container_status.get("state") or {}
        waiting = state.get("waiting") or {}
        if diagnosis := _diagnose_container_waiting(name, waiting):
            return diagnosis

    for container_status in container_statuses:
        name = container_status.get("name", "")
        state = container_status.get("state") or {}
        terminated = state.get("terminated") or {}
        if diagnosis := _diagnose_container_terminated(name, terminated):
            return diagnosis

    # Pod-level scheduling failures.
    for condition in status.get("conditions", []) or []:
        if (
            condition.get("type") == "PodScheduled"
            and condition.get("reason") == "Unschedulable"
        ):
            message = condition.get("message") or ""
            return InfrastructureDiagnosis(
                level=DiagnosisLevel.WARNING,
                summary="Pod is unschedulable",
                detail=message,
                resolution=(
                    "Check that the cluster has nodes with sufficient resources "
                    "and that any node selectors, affinities, or tolerations can "
                    "be satisfied."
                ),
            )

    # Pod-level eviction.
    if status.get("reason") == "Evicted":
        message = status.get("message") or ""
        return InfrastructureDiagnosis(
            level=DiagnosisLevel.WARNING,
            summary="Pod was evicted",
            detail=message,
            resolution=(
                "Check node resource pressure and pod resource requests to avoid "
                "future evictions."
            ),
        )

    return None
